const esc=(s='')=>String(s).replace(/[&<>'"]/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;',"'":'&#39;','"':'&quot;'}[c]));
function arrayish(value){
  if(Array.isArray(value))return value;
  if(!value||typeof value!=='object')return [];
  for(const key of ['items','data','results','planets','campaigns','assignments','dispatches','events','stations','sectors','factions']){
    if(Array.isArray(value[key]))return value[key];
  }
  const vals=Object.values(value);
  return vals.length&&vals.every(x=>x&&typeof x==='object'&&!Array.isArray(x))?vals:[];
}
function numberDeep(value,keys,maxDepth=4){
  if(value==null)return null;
  const wanted=new Set(keys||[]),queue=[[value,0]],seen=new Set();
  while(queue.length){
    const [node,depth]=queue.shift();
    if(!node||typeof node!=='object'||seen.has(node))continue;
    seen.add(node);
    for(const [key,raw] of Object.entries(node)){
      if(wanted.has(key)){
        const n=typeof raw==='number'?raw:Number(String(raw??'').replace(/[,\s]/g,''));
        if(Number.isFinite(n))return n;
      }
      if(depth<maxDepth&&raw&&typeof raw==='object')queue.push([raw,depth+1]);
    }
  }
  return null;
}
function firstText(value,keys,maxDepth=4){
  if(value==null)return '';
  const wanted=new Set(keys||[]),queue=[[value,0]],seen=new Set();
  while(queue.length){
    const [node,depth]=queue.shift();
    if(!node||typeof node!=='object'||seen.has(node))continue;
    seen.add(node);
    for(const [key,raw] of Object.entries(node)){
      if(wanted.has(key)&&typeof raw==='string'&&raw.trim())return raw.trim();
      if(depth<maxDepth&&raw&&typeof raw==='object')queue.push([raw,depth+1]);
    }
  }
  return '';
}
const val=v=>(v===null||v===undefined||v==='')?t('unknown'):v;
const localeName=(x)=>{if(!x)return '';const loc=I18N.locale||'en';return x.nameI18n?.[loc]||x.name||''};
const localePassive=(x)=>{if(!x)return '';const loc=I18N.locale||'en';return term(x.passiveI18n?.[loc]||x.passive||'')};
const cryptoRand=()=>{try{const a=new Uint32Array(1);crypto.getRandomValues(a);return a[0]/4294967296}catch{return Math.random()}};
function shuffleArray(input){const a=[...input];for(let i=a.length-1;i>0;i--){const j=Math.floor(cryptoRand()*(i+1));[a[i],a[j]]=[a[j],a[i]]}return a}
function tickerPool(){const loc=I18N.locale||'en';return (window.HD2_TICKER?.[loc]||window.HD2_TICKER?.[loc?.split('-')[0]]||window.HD2_TICKER?.en||[]).filter(Boolean)}
function newTickerCycle(previousFirst=''){let a=shuffleArray(tickerPool());if(a.length>1&&previousFirst&&a[0]===previousFirst)[[a[0],a[1]]]=[a[1],a[0]];return a}
function normalizeCallIn(value){
  // Stratagem input search intentionally accepts direction arrows only.
  // WASD remains an internal storage format and is never a user-facing query syntax.
  const raw=String(value||'');
  const arrows=[...raw].filter(c=>'↑←↓→'.includes(c));
  if(!arrows.length)return '';
  const map={'↑':'W','←':'A','↓':'S','→':'D'};
  return arrows.map(c=>map[c]).join('');
}
