function term(v){
  if(v===null||v===undefined||v==='')return v;
  if(typeof v!=='string')return v;
  if(termMap[v])return t(termMap[v]);
  const map=dataLexicon[I18N.locale]||dataLexicon[I18N.locale.split('-')[0]]||{};
  if(map[v])return map[v];
  const anti=v.match(/^Anti-Tank\s+([IVX]+)$/);if(anti)return `${map['Anti-Tank']||'Anti-Tank'} ${anti[1]}`;
  const ap=v.match(/^(Light|Medium|Heavy) Armor Penetrating$/);if(ap)return `${term(ap[1])} ${map['Armor Penetrating']||'Armor Penetrating'}`;
  if(v.includes(' / '))return v.split(' / ').map(x=>term(x)).join(' / ');
  return v;
}
