function catalogHero(kind){const title={weapons:t('weaponPageTitle'),stratagems:t('stratPageTitle'),armor:t('armorPageTitle'),enemies:t('enemies')}[kind];const sub={weapons:t('weaponPageSub'),stratagems:t('stratPageSub'),armor:t('armorPageSub'),enemies:t('database')}[kind];return pageHero(t('database'),title,sub,`${D[kind]?.length||0} ${t('records')}`)}
