    {title:t('combatStats'),rows:[[t('type'),term(x.type)],[t('permitType'),term(x.permit)],[t('role'),term(x.role)],[t('traits'),x.traits?.length?x.traits:null]]},
    {title:t('acquisitionStats'),rows:[[t('unlockLevel'),x.level],[t('cost'),x.cost],[t('source'),term(x.source)],[t('verifiedPatch'),x.lastVerifiedPatch]]}
