function renderDetailGroups(kind,x){return `<div class="detail-groups">${itemDetailGroups(kind,x).map(g=>`<section class="detail-group"><div class="detail-group-head"><span>${esc(g.title)}</span><i>${t('localVerifiedData')}</i></div>${detailRows(g.rows)}</section>`).join('')}</div>`}
