function referenceBlock(x){if(!x?.referenceUrl)return'';return `<div class="detail-reference"><a href="${esc(x.referenceUrl)}" target="_blank" rel="noreferrer">${t('communityReference')} ↗</a><span>${t('referenceHint')}</span></div>`}
